sp_widget.css:
// Grays
$gray-base: #000000;
$gray-dark: lighten($gray-base, 18.04%);
$gray-darker: lighten($gray-base, 8.24%);
$gray-light: lighten($gray-base, 40%);
$gray-lighter: lighten($gray-base, 94.51%);
$gray: lighten($gray-base, 29.02%);

////// Branding variables //////
// should always end with !default and no other variable should have !default
$brand-primary: #E30613 !default;
$body-bg: #ffffff !default;
$brand-success: #007A33 !default;
$state-success-text: darken(desaturate(adjust-hue($brand-success, 3), 15.64%), 34.31) !default;
$sp-navbar-divider-color: #0F5C36 !default;
$text-color: $gray-dark !default;
$navbar-inverse-link-hover-color: #FCD34D !default;
$navbar-inverse-bg: #00532B !default;
$brand-warning: #E8A200 !default;
$brand-danger: #B10510 !default;
$sp-tagline-color: #ffffff !default;
$navbar-inverse-link-active-color: $sp-tagline-color !default;
$navbar-inverse-link-color: #C9D8CE !default;
$brand-info: #3FA66B !default;
$link-color: #C81420 !default;
$sp-logo-margin-x: 15px !default;
$text-muted: $gray-light !default;
////////////////////////////////////

// Link hover decoration
$link-hover-decoration: underline !default;

// SPAR theme variables
$brand-primary-dark: darken($brand-primary, 20%);
$brand-primary-darker: #7A0308 !default;
$brand-primary-light: #F3949B !default;
$brand-primary-lighter: #FBC7CA !default;
$brand-primary-lightest: #FDF2F2 !default;
$dropdown-link-disabled-color: $gray-light;
$link-hover-color: darken(desaturate(adjust-hue($link-color, 1), 0.42%), 16.67);
$navbar-inverse-link-active-bg: #003D1F;
$navbar-inverse-link-hover-bg: #00713F;
$panel-primary-border: $brand-primary;
$panel-primary-heading-bg: $brand-primary;
$panel-primary-text: #ffffff;
$primary: $brand-primary;
$input-border-focus: #E30613;
$quicklinks-background: #FDF2F2;
$btn-success-bg: $brand-success;
$btn-default-color: #2e2e2e;
$btn-primary-color: #ffffff;
$btn-primary-bg: $brand-primary;
$btn-primary-border: darken($btn-primary-bg, 5%);
$btn-success-bg: $brand-success;
$btn-success-border: darken($btn-success-bg, 5%);
$btn-success-color: darken(desaturate(adjust-hue($brand-success, 3), 15.64%), 34.31);
$btn-disabled-opacity: 0.25;
$component-active-color: $gray;
$component-active-bg: #f5f5f5;
$state-danger-bg: lighten(saturate(adjust-hue($brand-danger, 354), 42.52%), 42.94);
$state-danger-border: #B10510;
$state-danger-text: #64100A;
$state-info-bg: lighten(desaturate($brand-info, 3.27%), 19.02);
$state-info-border: $brand-info;
$state-info-text: darken(desaturate(adjust-hue($brand-info, 1), 2.75%), 41.57);
$state-success-bg: lighten(saturate($brand-success, 3.67%), 28.24);
$state-success-border: $brand-success;
$state-warning-bg: lighten(saturate(adjust-hue($brand-warning, -3), 17.70%), 29.61);
$state-warning-border: $brand-warning;
$state-warning-text: darken(desaturate(adjust-hue($brand-warning, -4), 20.32%), 44.31);
$alert-danger-bg: $state-danger-bg;
$alert-danger-border: $state-danger-border;
$alert-danger-text: $state-danger-text;
$alert-info-bg: $state-info-bg;
$alert-info-border: $state-info-border;
$alert-info-text: $state-info-text;
$alert-success-bg: $state-success-bg;
$alert-success-border: $state-success-border;
$alert-success-text: $state-success-text;
$alert-warning-bg: $state-warning-bg;
$alert-warning-border: $state-warning-border;
$alert-warning-text: $state-warning-text;

// To get service status messages consistent with brand colors
$primary: $brand-primary;
$warning: $brand-warning;
$success: $brand-success;
$info: $brand-info;
$danger: $brand-danger;
$input-border-placeholder: white;

// Service Catalog panel hover highlight
$panel-list-item: lighten(desaturate(adjust-hue($panel-primary-heading-bg, -6), 20.79%), 58.04);
$panel-primary-heading-bg: #C81420;

$multiple-issues-color: #7070B3;
$no-issue-color: lighten($brand-success, 40%);
$planned-maintenance-color: lighten($brand-info, 35%);
$service-degredation-color: lighten($brand-warning, 40%);
$service-outage-color: lighten($brand-danger, 45%);

$no-issue-border-color: $brand-success;
$planned-maintenance-border-color: $brand-info;
$service-degredation-border-color: $brand-warning;
$service-outage-border-color: $brand-danger;

$no-issues-text: $state-success-text;
$planned-maintenance-text: $state-info-text;
$service-degredation-text: $state-info-text;
$service-outage-text: $state-danger-bg;

$login-btn-bg: $btn-primary-bg;
$login-btn-border: $btn-primary-border;

$qa-tag-color: $state-info-text;
$qa-tag-bg: $state-info-bg;
$qa-tag-border: $state-info-bg;
$qa-tag-hover-color: darken($qa-tag-color, 10%);
$qa-tag-hover-bg: darken($qa-tag-bg, 10%);

$qa-thread-tag-color: $state-info-text;
$qa-thread-tag-bg: $state-info-bg;
$qa-thread-tag-hover-color: darken($qa-thread-tag-color, 10%);
$qa-thread-tag-hover-bg: darken($qa-thread-tag-bg, 10%);

$qa-panel-link-color: $link-color;
$select2-container-active: $input-border-focus;

$not-webkit-outline-color: $input-border-focus;
$webkit-outline-color: $input-border-focus;

$label-success-bg: lighten(saturate($brand-success, 3.67%), 28.24);
$label-info-bg: lighten(desaturate($brand-info, 3.27%), 19.02);
$label-warning-bg: lighten(saturate(adjust-hue($brand-warning, -3), 17.70%), 29.61);
$label-danger-bg: lighten(saturate(adjust-hue($brand-danger, 354), 42.52%), 42.94);
$label-primary-bg: #B10510;
$data-table-selected: $brand-primary;

$button-selected-color: $btn-primary-bg;
$dropdown-link-active-bg: $brand-primary;
$dropdown-link-active-color: #ffffff;
$widget-editor-fa-bg: $brand-primary;

$input-border-tab-focus: $input-border-focus;

$fav-star-color: darken($brand-warning, 20%);
$fav-star-color-off: #ffffff;
$fav-star-outline-color: #6b611f;
$fav-star-outline: -1px 0 $fav-star-outline-color, 0 1px $fav-star-outline-color, 1px 0 $fav-star-outline-color, 0 -1px $fav-star-outline-color;

$sc-field-error-color: #1a424b;
$qa-star-color-on: $brand-warning;
$qa-star-color-off: #ffffff;

$list-group-link-color: $brand-primary;
$list-group-hover-bg: lighten($panel-primary-heading-bg, 40%);

$accessible-placeholder-gray: #565656;

// ── Icon colors ──
$icon-color: $brand-success;
$icon-color-hover: $brand-primary;
$icon-color-active: $brand-primary-dark;
$icon-color-muted: $gray-light;
$icon-color-inverse: #ffffff;

// ── Widget/category icon chip background ──
$widget-icon-color: $brand-success;
$widget-icon-bg: $no-issue-color;

// ── Needed by the Icon Link widget ──
$icon-link-glyph-color: #ffffff;
$text-secondary: #64748B;

// ── Futuristic accents: gradients + glow ──
$gradient-primary-start: $brand-primary;
$gradient-primary-end: darken($brand-primary, 15%);
$gradient-success-start: $brand-success;
$gradient-success-end: darken($brand-success, 15%);
$glow-primary: rgba(227, 6, 19, 0.45);
$glow-success: rgba(0, 122, 51, 0.45);
$glass-bg: rgba(255, 255, 255, 0.65);
$glass-border: rgba(255, 255, 255, 0.4);
/*
===============================================================================
ICON LINK WIDGET — SPAR Futuristic edition
Paste into the widget's CSS field (or the theme's CSS field if used sitewide)
Adds gradients, glow, float and bounce to the stock top/circle/color-box icon
link styles, using the same tokens as the rest of the theme.
===============================================================================
*/

.iconlink {
  padding: 3px 0;
}
.iconlink a label,h2 {
  display: block;
  font-size: 2.5rem;
  font-weight: 300;
  line-height: 1.1;
  padding: 0;
  margin: 0 0 10px 0;
}

/* TOP ICON ---------- */
a.top_icon {
  display: block;
  padding: 20px;
  text-align: center;
  border-radius: 14px;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1), background 280ms ease;
}
a.top_icon .fa {
  display: block;
  text-align: center;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1), filter 280ms ease;
}
a.top_icon:hover {
  background: rgba(227, 6, 19, 0.06);
  transform: translateY(-3px);
}
a.top_icon:hover .fa {
  transform: scale(1.18) rotate(-4deg);
  filter: drop-shadow(0 4px 10px rgba(227, 6, 19, 0.35));
}

/* CIRCLE ICON ---------- */
@keyframes circleIconFloat {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-3px); }
}
a.circle_icon {
  display: block;
  padding: 20px 0px 20px 70px;
  position: relative;
}
a.circle_icon .fa {
  position: absolute;
  left: 0px;
  top: 10px;
  width: 46px;
  height: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: linear-gradient(135deg, $gradient-success-start 0%, $gradient-success-end 100%);
  box-shadow: 0 4px 14px $glow-success;
  animation: circleIconFloat 3.2s ease-in-out infinite;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 280ms ease;
}
a.circle_icon .fa-stack-1x {
  color: $icon-link-glyph-color;
  position: relative;
}
a.circle_icon:hover .fa {
  transform: scale(1.15) rotate(-6deg);
  box-shadow: 0 8px 22px $glow-success;
  animation-play-state: paused;
}

/* COLOR BOX ---------- */
a.color_box {
  display: block;
  position: relative;
  padding: 20px 20px 20px 82px;
  border-radius: 14px;
  margin-bottom: 20px;
  overflow: hidden;
  color: $panel-primary-text;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 280ms ease;
}
a.color_box::after {
  content: "";
  position: absolute;
  top: 0;
  left: -60%;
  width: 40%;
  height: 100%;
  background: linear-gradient(120deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.35) 50%, rgba(255,255,255,0) 100%);
  transform: skewX(-20deg);
  transition: left 550ms ease;
}
a.color_box:hover::after {
  left: 130%;
}
a.color_box:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.18);
}
a.color_box .fa {
  position: absolute;
  left: 20px;
  top: 20px;
  width: 42px;
  text-align: center;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1);
}
a.color_box:hover .fa {
  transform: scale(1.15);
}

/* Gradient icon-link backgrounds, replacing flat fills */
.icon-link-background-primary {
  background: linear-gradient(135deg, $gradient-primary-start 0%, $gradient-primary-end 100%);
}
.icon-link-background-info {
  background: linear-gradient(135deg, $brand-info 0%, darken($brand-info, 15%) 100%);
}
.icon-link-background-success {
  background: linear-gradient(135deg, $gradient-success-start 0%, $gradient-success-end 100%);
}
.icon-link-background-warning {
  background: linear-gradient(135deg, $brand-warning 0%, darken($brand-warning, 12%) 100%);
}
.icon-link-background-danger {
  background: linear-gradient(135deg, $brand-danger 0%, darken($brand-danger, 12%) 100%);
}
.icon-link-background-default {
  background: linear-gradient(135deg, $gradient-primary-start 0%, $gradient-primary-end 100%);
}

/* Text link colors — unchanged logic, bolder hover lift */
.text-primary {
  color: $brand-primary-dark;
  transition: color 200ms ease, transform 200ms ease;

  &:hover {
    color: $brand-primary-darker;
    transform: translateX(2px);
  }
}
.text-info {
  color: $brand-info;
  transition: color 200ms ease, transform 200ms ease;

  &:hover {
    color: darken($brand-info, 20%);
    transform: translateX(2px);
  }
}
.text-success {
  color: $brand-success;
  transition: color 200ms ease, transform 200ms ease;

  &:hover {
    color: darken($brand-success, 20%);
    transform: translateX(2px);
  }
}
.text-warning {
  color: $brand-warning;
  transition: color 200ms ease, transform 200ms ease;

  &:hover {
    color: darken($brand-warning, 20%);
    transform: translateX(2px);
  }
}
.text-danger {
  color: $brand-danger;
  transition: color 200ms ease, transform 200ms ease;

  &:hover {
    color: darken($brand-danger, 20%);
    transform: translateX(2px);
  }
}
.text-default {
  color: $brand-primary-dark;
  transition: color 200ms ease, transform 200ms ease;

  &:hover {
    color: $brand-primary-darker;
    transform: translateX(2px);
  }
}
.text-muted {
  color: $text-secondary;
}

.high-contrast {
  .text-primary {
    color: darken($brand-primary-dark, 10%);
  }
  .text-info {
    color: darken($brand-info, 10%);
  }
  .text-success {
    color: darken($brand-success, 10%);
  }
  .text-warning {
    color: darken($brand-warning, 10%);
  }
  .text-danger {
    color: darken($brand-danger, 10%);
  }
  .text-default {
    color: darken($brand-primary-dark, 10%);
  }
}
